const mongoose = require('mongoose');

const passkeySchema = new mongoose.Schema({
  user: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true,
    index: true
  },

  // Unique identifier generated by the authenticator
  credentialId: {
    type: String,
    required: true,
    unique: true
  },

  // Public key used by the backend to verify assertions
  publicKey: {
    type: String,
    required: true
  },

  // WebAuthn-specific user identifier (not the email)
  webauthnUserID: {
    type: String,
    required: true
  },

  counter: {
    type: Number,
    default: 0
  },

  transports: {
    type: [String],
    default: []
  },

  deviceType: {
    type: String,
    default: 'singleDevice'
  },

  backedUp: {
    type: Boolean,
    default: false
  },

  createdAt: {
    type: Date,
    default: Date.now
  },

  lastUsedAt: {
    type: Date,
    default: null
  }
});

module.exports = mongoose.model('Passkey', passkeySchema);